package com.shms.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="admissions") public class Admission { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="admission_number",nullable=false,unique=true) private String admissionNumber; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="patient_id",nullable=false) private Patient patient; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="doctor_id",nullable=false) private Doctor doctor; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="bed_id",nullable=false) private Bed bed; @Column(name="admission_date",nullable=false) private LocalDateTime admissionDate; @Column(name="discharge_date") private LocalDateTime dischargeDate; private String reason; @Column(columnDefinition="TEXT") private String diagnosis; @Column(columnDefinition="TEXT") private String notes; @Enumerated(EnumType.STRING) private Status status=Status.ADMITTED; public enum Status{ADMITTED,DISCHARGED,TRANSFERRED,CANCELLED} @PrePersist void pre(){if(admissionDate==null)admissionDate=LocalDateTime.now();} public Long getId(){return id;} public void setId(Long v){id=v;} public String getAdmissionNumber(){return admissionNumber;} public void setAdmissionNumber(String v){admissionNumber=v;} public Patient getPatient(){return patient;} public void setPatient(Patient v){patient=v;} public Doctor getDoctor(){return doctor;} public void setDoctor(Doctor v){doctor=v;} public Bed getBed(){return bed;} public void setBed(Bed v){bed=v;} public LocalDateTime getAdmissionDate(){return admissionDate;} public void setAdmissionDate(LocalDateTime v){admissionDate=v;} public LocalDateTime getDischargeDate(){return dischargeDate;} public void setDischargeDate(LocalDateTime v){dischargeDate=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public String getDiagnosis(){return diagnosis;} public void setDiagnosis(String v){diagnosis=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} public Status getStatus(){return status;} public void setStatus(Status v){status=v;} }
